import java.io.Reader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Properties;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Scenario {
    private static final class Gate { int value; }
    private static final Gate SHARED = new Gate();

    static int runUnit(boolean useSharedMonitor) {
        Gate a = useSharedMonitor ? SHARED : new Gate();
        Object b = new Object();
        synchronized (a) {
            synchronized (b) {
                synchronized (a) { a.value++; }
            }
            return a.value;
        }
    }

    public static void main(String[] args) throws Exception {
        Properties settings = new Properties();
        try (Reader reader = Files.newBufferedReader(Path.of(args[0]))) {
            settings.load(reader);
        }
        boolean useSharedMonitor = Boolean.parseBoolean(settings.getProperty("useSharedMonitor"));
        try (var workers = Executors.newFixedThreadPool(8)) {
            var results = new ArrayList<Future<Integer>>();
            for (int i = 0; i < 1000; i++) {
                results.add(workers.submit(() -> runUnit(useSharedMonitor)));
            }
            long sum = 0;
            for (Future<Integer> result : results) sum += result.get();
            System.out.println(sum);
        }
    }
}
